'use strict';

const EventEmitter = require('events');
const nconf = require('nconf');

let real;
let noCluster;
let singleHost;

function get() {
	if (real) {
		return real;
	}

	let pubsub;

	if (!nconf.get('isCluster')) {
		if (noCluster) {
			real = noCluster;
			return real;
		}
		noCluster = new EventEmitter();
